<script setup lang="ts">
import {apiError} from './apiError';
import {ref,watch} from 'vue';
const props=defineProps<{projectId:string;csv:string}>();const emit=defineEmits<{apply:[id:string]}>();
const mode=ref('fragility');const rate=ref(.02);const repair=ref(6);const resource=ref('grid_channel');const rating=ref(4000);
const name=ref('强风设备故障场景');const seed=ref(42);const hazard=ref('');const list=ref<any[]>([]);const selected=ref<any>(null);const working=ref(false);const error=ref('');
const devices=ref<any[]>([{device_id:'GRID-01',device_type:'grid_channel',rated_kw:4000,a_wind:.5,b_wind:25,derate_factor:.5,recovery_factor:.8}]);
const types=[['grid_channel','上级电网'],['emergency_gen','应急发电'],['storage','储能功率'],['renewable','风光合计'],['transformer','变压器']];
async function api(path:string,options?:RequestInit){const r=await fetch(path,options);const d=await r.json();if(!r.ok)throw Error(apiError(d.detail));return d}
function template(){hazard.value='timestamp,wind_speed\n'+props.csv.trim().split(/\r?\n/).slice(1).map(line=>line.split(',')[0]+',20').join('\n')+'\n';error.value='已按当前源荷时间轴填入20m/s假设风速，请按实际数据修改。'}
async function refresh(){if(!props.projectId)return;try{list.value=await api('/api/scenarios?project_id='+props.projectId)}catch(e){error.value=String(e)}}
async function generate(){working.value=true;error.value='';try{selected.value=await api(mode.value==='fragility'?'/api/scenarios/faults':'/api/scenarios/sequential',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(mode.value==='fragility'?{project_id:props.projectId,name:name.value,seed:seed.value,hazard_csv:hazard.value,devices:devices.value}:{project_id:props.projectId,name:name.value,seed:seed.value,csv:props.csv,resource:resource.value,rated_kw:rating.value,rate_per_hour:rate.value,repair_hours:repair.value})});await refresh()}catch(e){error.value=String(e)}finally{working.value=false}}
async function inspect(id:string){try{selected.value=await api('/api/scenarios/'+id);mode.value=selected.value.repair_hours?'sequential':'fragility';name.value=selected.value.name;seed.value=selected.value.seed;if(mode.value==='sequential'){rate.value=selected.value.rate_per_hour;repair.value=selected.value.repair_hours;resource.value=selected.value.resource;rating.value=selected.value.rated_kw}else{hazard.value=selected.value.hazard_csv||'';devices.value=selected.value.devices}}catch(e){error.value=String(e)}}
watch(()=>props.projectId,()=>{selected.value=null;refresh()},{immediate:true});
</script>
<template><p class="notice">{{mode==='fragility'?'风速脆弱性模型：采用风速与Sigmoid参数逐小时独立抽样，不模拟连续修复。':'连续故障模型：以每小时失效率λ生成故障，故障持续到设定修复时长结束；逐小时转移概率为1-exp(-λ)。'}}调用课题2原始代码，参数须校准；生成场景只在主动选择后用于平衡计算。</p><p v-if="error" class="notice">{{error}}</p><div class="grid"><article><h3>场景定义</h3><label class="field">故障模型<select v-model="mode"><option value="fragility">风速脆弱性逐时抽样</option><option value="sequential">连续故障与修复</option></select></label><label class="field">场景名称<input v-model="name" :disabled="working"></label><label class="field">随机种子<input type="number" min="0" v-model.number="seed" :disabled="working"></label><template v-if="mode==='fragility'"><button @click="template" :disabled="working">从源荷时间轴建立风速模板</button><textarea v-model="hazard" :disabled="working" placeholder="timestamp,wind_speed"></textarea><p>风速单位m/s；2–168小时，必须与计算源荷时间轴一致。</p></template><template v-else><p>沿用当前工程源荷时间轴；不使用风速模板。</p><label class="field">资源类型<select v-model="resource"><option v-for="[key,label] in types" :value="key">{{label}}</option></select></label><label class="field">可用容量上限 / kW<input type="number" v-model.number="rating"></label><label class="field">每小时失效率 λ<input type="number" step=".01" v-model.number="rate"></label><label class="field">修复时长 / h<input type="number" v-model.number="repair"></label><button @click="generate" :disabled="working">生成连续状态场景</button></template></article><article><h3>已保存场景</h3><p v-if="!list.length">尚无场景，请配置参数后生成。</p><button v-for="s in list" class="record" @click="inspect(s.id)">{{s.name}} · {{s.created}}</button></article></div><article v-if="mode==='fragility'"><h3>设备与脆弱性参数</h3><div class="scroll"><table><tr><th>编号</th><th>类型</th><th>额定kW</th><th>斜率 a</th><th>中点 b / m/s</th><th>降额系数</th><th>恢复系数</th><th></th></tr><tr v-for="(d,i) in devices"><td><input v-model="d.device_id" :disabled="working"></td><td><select v-model="d.device_type" :disabled="working"><option v-for="[key,label] in types" :value="key">{{label}}</option></select></td><td v-for="k in ['rated_kw','a_wind','b_wind','derate_factor','recovery_factor']"><input v-model.number="d[k]" type="number" step="any" :disabled="working"></td><td><button @click="devices.splice(i,1)" :disabled="working||devices.length===1">移除</button></td></tr></table></div><div class="actions"><button @click="devices.push({device_id:'DEV-'+(devices.length+1),device_type:'storage',rated_kw:500,a_wind:.5,b_wind:25,derate_factor:.5,recovery_factor:.8})" :disabled="working">＋ 添加设备</button><button @click="generate" :disabled="working||!projectId">{{working?'正在生成…':'生成并保存场景'}}</button></div></article><article v-if="selected"><h3>{{selected.name}} / 逐时设备状态</h3><p>{{selected.scope}}</p><button class="primary" @click="emit('apply',selected.id)">将此场景应用到电力电量平衡</button><p v-if="selected.repair_hours">修复时长 {{selected.repair_hours}} h；失效率 {{selected.rate_per_hour}} /h；故障起始事件 {{selected.failures?.length || 0}} 次。维修期间保持故障，不重复抽样。</p><p>随机种子 {{selected.seed}}；设备状态共{{selected.states.length}}条。下表显示前100条，完整快照已存入本地数据库。</p><div class="scroll"><table><tr><th>时间</th><th>设备</th><th>抽样转移概率</th><th>状态</th><th>可用容量 / kW</th></tr><tr v-for="r in selected.states.slice(0,100)"><td>{{r.timestamp}}</td><td>{{r.device_id}}</td><td>{{(r.fault_prob*100).toFixed(2)}}%</td><td>{{({normal:'正常',derated:'降额',failed:'故障',recovery:'恢复'} as Record<string,string>)[r.state]}}</td><td>{{r.available_kw}}</td></tr></table></div></article></template>
<style scoped>.scroll{margin:15px 0}td input{width:100px;padding:8px;border:1px solid #c8dcdf}select{padding:8px}.actions{flex-wrap:wrap}.field input{width:60%}</style>
